const C={ink:{r:.086,g:.082,b:.059},ink2:{r:.29,g:.28,b:.26},ink3:{r:.42,g:.41,b:.39},paper:{r:.984,g:.976,b:.957},tint:{r:.945,g:.929,b:.89},line:{r:.85,g:.835,b:.8},acc:{r:.54,g:.353,b:.169},accbg:{r:.957,g:.914,b:.859},white:{r:1,g:1,b:1}};
await Promise.all(['Regular','Medium','Semi Bold'].map(s=>figma.loadFontAsync({family:'Inter',style:s})));
const F=c=>[{type:'SOLID',color:c}];
const T=(s,z,c,st)=>{const t=figma.createText();t.fontName={family:'Inter',style:st||'Regular'};t.fontSize=z;t.fills=F(c||C.ink2);t.characters=s;t.lineHeight={unit:'PERCENT',value:145};return t};
const B=(dir,o={})=>{const f=figma.createAutoLayout(dir);f.itemSpacing=o.gap||0;f.paddingTop=f.paddingBottom=o.py||0;f.paddingLeft=f.paddingRight=o.px||0;f.fills=o.fill?F(o.fill):[];if(o.stroke){f.strokes=F(o.stroke);f.strokeWeight=1}if(o.r)f.cornerRadius=o.r;f.name=o.name||'Frame';return f};
const add=(p,n)=>{p.appendChild(n);if(n.type==='TEXT')n.textAutoResize='HEIGHT';n.layoutSizingHorizontal='FILL';return n};
const ov=(s,c)=>{const t=T(s.toUpperCase(),11,c||C.acc,'Medium');t.letterSpacing={unit:'PERCENT',value:14};return t};
const LOGO='<svg xmlns="http://www.w3.org/2000/svg" width="256" height="256" viewBox="0 0 256 256" fill="none"><path fill="#16150F" d="M170.764 194 128 120.15l-19.112 34.08 43.382 15.365H98.255L84.948 193.79a73.273 73.273 0 0 1-21.782-25.347A72.513 72.513 0 0 1 55 134.907a73.363 73.363 0 0 1 1.483-14.694 72.455 72.455 0 0 1 10.984-26.07 73.193 73.193 0 0 1 32.118-26.416 72.695 72.695 0 0 1 13.703-4.246 73.805 73.805 0 0 1 29.424 0 72.64 72.64 0 0 1 26.103 10.97 73.134 73.134 0 0 1 26.448 32.077 72.452 72.452 0 0 1 4.254 13.686 73.46 73.46 0 0 1-.665 32.321 72.698 72.698 0 0 1-15.636 30.063A73.448 73.448 0 0 1 170.764 194z"/></svg>';
let MODE='tpl';
const val=(ex,h)=>{if(MODE==='ex'&&ex){const f=B('VERTICAL',{px:14,py:12,fill:C.accbg,r:4,name:'Value'});const t=T(ex,14,C.ink);f.appendChild(t);t.textAutoResize='HEIGHT';t.layoutSizingHorizontal='FILL';return f}const r=figma.createRectangle();r.resize(100,h||80);r.fills=F(C.tint);r.cornerRadius=4;r.name='Area';return r};
const card=(label,hint,ex,h)=>{const k=B('VERTICAL',{gap:8,px:20,py:20,fill:C.white,stroke:C.line,r:8,name:label});k.appendChild(ov(label));if(hint)add(k,T(hint,13,C.ink3));add(k,val(ex,h));return k};
const row=(items,gap)=>{const r=B('HORIZONTAL',{gap:gap||20,name:'Row'});items.forEach(n=>{r.appendChild(n);n.layoutSizingHorizontal='FILL';n.layoutSizingVertical='FILL'});return r};
const sec=(title,desc)=>{const s=B('VERTICAL',{gap:16,name:title||'Section'});if(title)s.appendChild(T(title,26,C.ink,'Medium'));if(desc)add(s,T(desc,14,C.ink3));return s};
const table=(heads,n,ex,widths,tplRows)=>{const t=B('VERTICAL',{fill:C.white,stroke:C.line,r:8,name:'Table'});t.clipsContent=true;const rows=MODE==='ex'&&ex?ex:(tplRows||Array.from({length:n},()=>heads.map(()=>'')));[heads,...rows].forEach((cells,ri)=>{const r=B('HORIZONTAL',{name:ri?'Row':'Header'});if(ri){r.strokes=F(C.line);r.strokeWeight=1;r.strokeTopWeight=0;r.strokeLeftWeight=0;r.strokeRightWeight=0;r.strokeBottomWeight=1}t.appendChild(r);r.layoutSizingHorizontal='FILL';cells.forEach((c,i)=>{const cell=B('VERTICAL',{px:14,py:ri?14:10,fill:ri?null:C.tint,name:'Cell'});if(c){const tx=T(ri?c:c.toUpperCase(),ri?13:11,ri?C.ink:C.ink3,ri?'Regular':'Medium');cell.appendChild(tx);tx.textAutoResize='HEIGHT';tx.layoutSizingHorizontal='FILL'}else{const sp=figma.createRectangle();sp.resize(10,28);sp.fills=[];cell.appendChild(sp)}r.appendChild(cell);if(widths&&widths[i]){cell.layoutSizingHorizontal='FIXED';cell.resize(widths[i],cell.height)}else cell.layoutSizingHorizontal='FILL';cell.layoutSizingVertical='FILL'})});return t};
const checkRow=(s,on)=>{const r=B('HORIZONTAL',{gap:12,py:10,name:'Check'});const b=figma.createRectangle();b.resize(18,18);b.cornerRadius=3;if(on){b.fills=F(C.acc)}else{b.fills=[];b.strokes=F(C.ink);b.strokeWeight=1.5}r.appendChild(b);add(r,T(s,15,C.ink));return r};
function brand(){const h=B('HORIZONTAL',{gap:16,py:20,name:'Brand bar'});h.counterAxisAlignItems='CENTER';h.strokes=F(C.line);h.strokeWeight=1;h.strokeTopWeight=0;h.strokeLeftWeight=0;h.strokeRightWeight=0;h.strokeBottomWeight=1;const lg=figma.createNodeFromSvg(LOGO);lg.name='Logo';lg.resize(44,44);h.appendChild(lg);const nm=B('VERTICAL',{gap:2,name:'Name'});nm.appendChild(T('Amit Kumar Tiwari',17,C.ink,'Semi Bold'));nm.appendChild(T('AI-native Design Methodology',12,C.ink3));h.appendChild(nm);const sp=B('HORIZONTAL',{name:'Spacer'});h.appendChild(sp);sp.layoutGrow=1;h.appendChild(T('designsbyamit.com',13,C.ink2,'Medium'));return h}
function header(spec){const h=B('VERTICAL',{gap:12,name:'Header'});h.appendChild(ov(spec.ov));const a=T(spec.title,56,C.ink,'Medium');a.letterSpacing={unit:'PERCENT',value:-2};h.appendChild(a);add(h,T(spec.sub,17,C.ink2));return h}
function banner(spec){const b=B('VERTICAL',{gap:6,px:28,py:22,fill:C.ink,r:10,name:'Example banner'});b.appendChild(ov('Worked example · fictional company',{r:.85,g:.65,b:.42}));add(b,T(spec.useCase,20,C.paper,'Medium'));add(b,T(spec.context,14,{r:.78,g:.76,b:.73}));return b}
function anatomy(a){const mk=(l,txt)=>{const k=B('VERTICAL',{gap:8,px:20,py:18,fill:C.white,stroke:C.line,r:8,name:l});k.appendChild(ov(l));add(k,T(txt,14,C.ink));return k};return row([mk('Purpose',a.purpose),mk('Builds on',a.inputs),mk('Feeds into',a.outputs)],16)}
function exitBlock(items){const s=sec('Done when',"Use the framework's core questions as the exit check before moving on.");const c=B('VERTICAL',{name:'Checks',fill:C.white,stroke:C.line,r:8,px:20,py:8});items.forEach(q=>add(c,checkRow(q,MODE==='ex')));add(s,c);return s}
function footer(){return T('© 2026 Amit Kumar Tiwari · AI-native Design Methodology · designsbyamit.com · Template v2.0',12,C.ink3)}
function frame(spec,name){const r=B('VERTICAL',{px:80,py:48,gap:48,fill:C.paper,name});r.resize(1440,200);r.primaryAxisSizingMode='AUTO';add(r,brand());add(r,header(spec));if(MODE==='ex')add(r,banner(spec));add(r,anatomy(spec.anatomy));return r}
async function build(spec,blocks){const p0=figma.currentPage;for(const c of [...p0.children])c.remove();p0.name='Template';MODE='tpl';const t=frame(spec,spec.title+' · Template');blocks(t);add(t,exitBlock(spec.exit));t.appendChild(footer());let p1=figma.root.children.find(p=>p.name.startsWith('Example'));if(!p1)p1=figma.createPage();p1.name='Example · NorthStar';for(const c of [...p1.children])c.remove();MODE='ex';const e=frame(spec,spec.title+' · Example (NorthStar)');blocks(e);add(e,exitBlock(spec.exit));e.appendChild(footer());p1.appendChild(e);e.x=0;e.y=0;t.x=0;t.y=0;return {t,e}}
